/bin/bash -lc "cat <<'EOF' > app/components/ThemeInfo.tsx
import { cookies, headers } from \"next/headers\";

function getPreferredLanguage(acceptLanguage: string | null): string {
  if ("'!acceptLanguage) {
    return "unknown";
  }

  const firstEntry = acceptLanguage.split(",")[0];
  const trimmed = firstEntry?.trim();

  return trimmed || "unknown";
}

export default function ThemeInfo() {
  const cookieStore = cookies();
  const themeCookie = cookieStore.get("theme");
  const theme = themeCookie?.value || "light";

  const headerStore = headers();
  const acceptLanguage = headerStore.get("accept-language");
  const preferredLanguage = getPreferredLanguage(acceptLanguage);

  return (
    <section>
      <h2>Current Preferences</h2>
      <p>Theme: {theme}</p>
      <p>Preferred language: {preferredLanguage}</p>
    </section>
  );
}
EOF'

